import logging
from taf.internal.aliasing import aliasing_scope
from taf.sw.qualcomm.license.licensekeeperclient import LicenseKeeperClient
from taf.sw.qualcomm.license.exception import MandatoryParameterNotProvided


class license(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_licensekeeperclients = aliasing_scope(name=__name__, lookup_arg='client',
                                                                     lookup_type=LicenseKeeperClient)

    def __init__(self):
        self._device = None

    def setup(self, launcher, port=None, timeout=None, alias=None):
        """
        startup and connect to the license keeper client, if the client is running, will not restart the client
        :param host: str, license keeper client host
        :param launcher: dict, ssh launcher
                         mandatory parameters: host, path, user, password
                         optional parameters: port
        :param port: int, port of service provided by license keeper

        :param alias: str optional, alias name.
.. code-block:: Robot

        Example of Test cases:
        *********************

        *** Settings ***
        Library    taf.sw.qualcomm.license   WITH NAME   license

        *** Variables ***

        *** Test Cases ***
        Get 5G qcat license
            ${launcher}=  Create Dictionary
            ...  host=10.57.130.xxx
            ...  path=/cygdrive/c/Users/tester/Desktop/QPM_LK1.3/ClientMain.exe
            ...  user=xxxx
            ...  password=xxxx

            license.setup    launcher=${launcher}
            license.login    username=xxx    password=xxxx
            license.get_licence_qcat_5g
            do your own test
            license.release_licence_qcat_5g
            license.logout
            license.teardown


        """
        deprecation_message = ("Starting QPM_LK client from library is not supported anymore in 1.1.0 "
                               "and higher version, the legacy attribute path in launcher "
                               "became useless along with the important change. \n"
                               "Please ensure the QPM_LK client is running already before the testing.")
        logging.warning(deprecation_message)
        if launcher is None:
            raise ValueError('Parameter launcher should not be None.')

        required_kwargs = {'host', 'path', 'user', 'password'}
        required_kwargs_result = required_kwargs.difference(launcher.keys())
        if required_kwargs_result:
            raise MandatoryParameterNotProvided('Missing parameters: {}'.format(required_kwargs_result))
        self._device = LicenseKeeperClient(launcher, port, timeout)
        self._device.setup()
        self.configured_licensekeeperclients.add(self._device, alias)
        return self._device

    @lookup_handler.implicit_lookup
    def teardown(self, client=None):
        """
        disconnect and shutdown to the license keeper client
        :param client: Union[str,LicenseKeeperClient] optional, alias name or client object.
        """
        client.teardown()

    @lookup_handler.implicit_lookup
    def login(self, username, password, timeout=30, client=None):
        """
        login the Licence Keeper server via license keeper client.

        :param username: str, Username that Licence Keeper account.
        :param password: str, Password that Licence Keeper account.
        :param timeout: int, default 30 seconds.
        :param client: Union[str,LicenseKeeperClient] optional, alias name or client object.
        """
        client.login(username, password, int(timeout))

    @lookup_handler.implicit_lookup
    def logout(self, timeout=30, client=None):
        """
        logout the Licence Keeper server via license keeper client.

        :param timeout: int, default 30 seconds.
        :param client: Union[str,LicenseKeeperClient] optional, alias name or client object.
        """
        client.logout(int(timeout))

    @lookup_handler.implicit_lookup
    def get_licence_qxdm_5g(self, timeout=30, retry=3, client=None):
        """
        get QXDM 5G licence from the Licence Keeper server.
        :param timeout: int, default 30 seconds.
        :param retry: int, default 3.
        :param client: Union[str,LicenseKeeperClient] optional, alias name or client object.
        """
        client.get_licence_qxdm_5g(int(timeout), int(retry))

